import json
import re
from datetime import datetime
from pathlib import Path
from typing import Any, Dict, List, Sequence

from tp5.types.image_shape import ImageShape
from tp5.types.samples import Samples

import numpy as np

# Default folder of the noisy patterns (generated by the `noisy` tool or saved from the /denoise page)
NOISY_DIR = "res/output/ej1/noisy"

# File names inside NOISY_DIR the server accepts (no folders)
_FILE = re.compile(r"[\w .+\-(),]+\.json")

def noisy_file_name(name: str) -> str:
    """Validate a noisy file name (`*.json`, no folders); raises ValueError otherwise."""
    if not _FILE.fullmatch(name) or name.startswith("."):
        raise ValueError(f"Invalid noisy file name: {name!r}.")
    return name

def save_noisy(
    directory: str | Path,
    dataset: str,
    label: str,
    index: int,
    shape: ImageShape,
    noise: Dict[str, Any],
    original: Sequence[float],
    noisy: Samples,
) -> Path:
    """
    Write `{noise type}-{YYYYmmdd-HHMMSS}.json` (with -2, -3... if that name exists) holding a pattern of
    the dataset and noisy versions of it. Values in [0, 1], images flattened channels-last.

    Returns:
        The written path.
    """
    now = datetime.now()
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)

    stem = f"{noise.get('type', 'manual')}-{label}-{now:%Y%m%d-%H%M%S}"
    path = directory / f"{stem}.json"
    suffix = 2
    while path.exists():
        path = directory / f"{stem}-{suffix}.json"
        suffix += 1

    noisy = np.atleast_2d(np.asarray(noisy, dtype=np.float64))
    content = {
        "dataset": dataset,
        "label": label,
        "index": int(index),
        "image_shape": {"height": shape.height, "width": shape.width, "channels": shape.channels},
        "noise": noise,
        "original": [float(v) for v in original],
        "noisy": np.round(noisy, 6).tolist(),
        "created": now.isoformat(timespec="seconds"),
    }
    # "x" mode: never overwrites, even if another process wrote the same name meanwhile
    with open(path, "x") as file:
        json.dump(content, file, indent=1)
    return path

def list_noisy(directory: str | Path) -> List[str]:
    """Names of the noisy files in `directory`, newest first."""
    directory = Path(directory)
    if not directory.is_dir():
        return []
    files = [path for path in directory.glob("*.json") if _FILE.fullmatch(path.name)]
    return [path.name for path in sorted(files, key=lambda p: p.stat().st_mtime, reverse=True)]

def load_noisy(directory: str | Path, name: str) -> Dict[str, Any]:
    """Content of a noisy file of `directory` (only plain names, never paths)."""
    path = Path(directory) / noisy_file_name(name)
    with open(path, "r") as file:
        return json.load(file)
